// e2e-test.mjs — load the extension in headless Chrome and prove the agent loop
// runs end-to-end: the NTP hub loads, a task runs via the agent-do loop, the
// result comes back, and usage is recorded.
import { CdpClient } from "./lib/cdp-client.ts";

const EXT = "/home/paulkinlan/chrome-agent-platform/extension";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const proc = new Deno.Command("/usr/bin/chromium", {
  args: [
    "--headless=new", "--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu",
    "--disable-extensions-except=" + EXT, "--load-extension=" + EXT,
    "--remote-debugging-port=0", "--user-data-dir=/tmp/cap-e2e", "about:blank",
  ],
  stdout: "piped", stderr: "piped",
}).spawn();

let port = 0;
for (let i = 0; i < 60; i++) {
  await sleep(250);
  const r = proc.stderr.getReader();
  const { value, done } = await r.read(); r.releaseLock();
  const line = done ? null : new TextDecoder().decode(value);
  if (line?.includes("DevTools listening")) { port = Number(line.match(/ws:\/\/127\.0\.0\.1:(\d+)/)?.[1] ?? 0); break; }
}
const version = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json();
const cdp = new CdpClient(version.webSocketDebuggerUrl);
await cdp.ready();

// find the service worker target (the extension)
const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const sw = targets.find((t) => t.type === "service_worker" && t.url.includes("chrome-extension://"));
if (!sw) { console.log("NO service worker found"); proc.kill(); Deno.exit(1); }
const extId = sw.url.split("/")[2];
console.log("extension id:", extId);

// open the NTP hub page
const page = await cdp.send("Target.createTarget", { url: `chrome-extension://${extId}/ntp/ntp.html` });
const { sessionId } = await cdp.send("Target.attachToTarget", { targetId: page.targetId, flatten: true });
const sess = (m, p = {}) => cdp.send(m, p, sessionId);
await sess("Page.enable"); await sess("Runtime.enable");
await sleep(2500); // let the page + service worker initialize

// check the hub rendered
const hub = await sess("Runtime.evaluate", {
  expression: `({ title: document.title, hasTask: !!document.querySelector('#task-input, input, textarea'), status: document.querySelector('#status')?.textContent ?? '' })`,
  returnByValue: true,
});
console.log("hub:", JSON.stringify(hub.result?.value));

// run a task via the message channel (what the chat/hub send does)
const runRes = await sess("Runtime.evaluate", {
  expression: `(async () => {
    const send = (type, payload) => new Promise((resolve) => chrome.runtime.sendMessage({ type, ...(payload ?? {}) }, (r) => resolve(r)));
    const res = await send("agent.run", { task: "summarize what the Chrome agent platform is", id: "e2e-" + Date.now() });
    return res;
  })()`,
  awaitPromise: true,
  returnByValue: true,
});
console.log("agent.run result:", JSON.stringify(runRes.result?.value)?.slice(0, 400));

// check usage was recorded
const usage = await sess("Runtime.evaluate", {
  expression: `(async () => { const r = await new Promise((resolve) => chrome.runtime.sendMessage({ type: "usage.get" }, resolve)); return r; })()`,
  awaitPromise: true,
  returnByValue: true,
});
const u = usage.result?.value;
console.log("usage.totals:", JSON.stringify(u?.totals));
console.log("usage.byModel:", JSON.stringify(u?.byModel)?.slice(0, 300));

// screenshot the hub
const shot = await sess("Page.captureScreenshot", { format: "png" });
const b64 = shot.data;
const bin = new Uint8Array(atob(b64).split("").map((c) => c.charCodeAt(0)));
await Deno.writeFile("/tmp/cap-e2e/hub.png", bin);

proc.kill();
Deno.exit(0);

