import { CdpClient } from "./lib/cdp-client.ts";
const EXT = "/home/paulkinlan/chrome-agent-platform/extension";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const proc = new Deno.Command("/usr/bin/chromium", {
  args: ["--headless=new","--no-sandbox","--disable-dev-shm-usage","--disable-gpu",
    "--disable-extensions-except="+EXT,"--load-extension="+EXT,
    "--remote-debugging-port=0","--user-data-dir=/tmp/cap-e2e2","about:blank"],
  stdout: "piped", stderr: "piped",
}).spawn();
let port = 0;
for (let i = 0; i < 60; i++) {
  await sleep(250);
  const r = proc.stderr.getReader(); const { value, done } = await r.read(); r.releaseLock();
  const line = done ? null : new TextDecoder().decode(value);
  if (line?.includes("DevTools listening")) { port = Number(line.match(/ws:\/\/127\.0\.0\.1:(\d+)/)?.[1] ?? 0); break; }
}
const version = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json();
const cdp = new CdpClient(version.webSocketDebuggerUrl);
await cdp.ready();
const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const sw = targets.find((t) => t.type === "service_worker");
const { sessionId } = await cdp.send("Target.attachToTarget", { targetId: sw.targetId, flatten: true });
const sess = (m, p = {}) => cdp.send(m, p, sessionId);
await sess("Runtime.enable"); await sess("Console.enable");
const logs = [];
cdp.on("Runtime.consoleAPICalled", (p, sid) => { if (sid === sessionId) logs.push(`[${p.type}] ${(p.args||[]).map(a=>a.value??a.description??'').join(' ')}`.slice(0,200)); });
cdp.on("Runtime.exceptionThrown", (p, sid) => { if (sid === sessionId) logs.push(`EXCEPTION: ${p.exceptionDetails?.exception?.description ?? p.exceptionDetails?.text ?? ''}`.slice(0,200)); });

// trigger the agent.run via a message
try {
  const r = await sess("Runtime.evaluate", {
    expression: `(async () => {
      const res = await new Promise((resolve) => chrome.runtime.sendMessage({ type: "agent.run", task: "hello", id: "diag-" + Date.now() }, (r) => resolve(r)));
      return res;
    })()`,
    awaitPromise: true, returnByValue: true,
  });
  console.log("agent.run res:", JSON.stringify(r.result?.value)?.slice(0,300));
} catch (e) {
  console.log("evaluate error:", String(e?.message ?? e).slice(0,200));
}
console.log("--- service worker console ---");
for (const l of logs) console.log(l);
proc.kill();
Deno.exit(0);
EOF
timeout 90 deno run -A e2e-diag.mjs 2>&1 | grep -vE "at (listOn|Object|ext:|WebSocket|__event|async|Module)" | tail -15

