const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const proc = new Deno.Command("/usr/bin/chromium", {
  args: ["--headless=new","--no-sandbox","--disable-dev-shm-usage","--disable-gpu",
    "--disable-extensions-except="+EXT,"--load-extension="+EXT,
    "--remote-debugging-port=0","--user-data-dir=/tmp/cap-e2e3","about:blank"],
  stdout: "piped", stderr: "piped",
}).spawn();
let port = 0;
for (let i = 0; i < 60; i++) {
  await sleep(250);
  const r = proc.stderr.getReader(); const { value, done } = await r.read(); r.releaseLock();
  const line = done ? null : new TextDecoder().decode(value);
  if (line?.includes("DevTools listening")) { port = Number(line.match(/ws:\/\/127\.0\.0\.1:(\d+)/)?.[1] ?? 0); break; }
}
await sleep(2000); // let the extension SW spawn
const version = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json();
const cdp = new CdpClient(version.webSocketDebuggerUrl);
