const sw = targets.find((t) => t.type === "service_worker" && t.url.includes("bnglkgljoaoggjnghjlohjlhfcgpokgf")) || targets.find((t) => t.type === "service_worker");
if (!sw) { console.log("NO SW"); proc.kill(); Deno.exit(1); }
const { sessionId } = await cdp.send("Target.attachToTarget", { targetId: sw.id, flatten: true });
const sess = (m, p = {}, t = 20000) => cdp.send(m, p, sessionId, t);
await sess("Runtime.enable");
const logs = [];
cdp.on("Runtime.consoleAPICalled", (p, sid) => { if (sid === sessionId) logs.push(`[${p.type}] ${(p.args||[]).map(a=>a.value??a.description??'').join(' ')}`.slice(0,160)); });

