  expression: `(async () => { try { const d = await navigator.storage.getDirectory(); const m = await d.getDirectoryHandle("memory", { create: true }); await m.getDirectoryHandle("origins", { create: true }); return "listOrigins path ok"; } catch (e) { return "err: " + String(e?.message ?? e); } })()`,
