let targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
await sleep(1500);
targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
// navigate a page to the NTP via a known ext id — read manifest to get a stable id? Instead use chrome://extensions
// simpler: create a target to the NTP using the id from the SW target (may need to wake it)
let extId = null;
for (const t of targets) {
  if (t.url.includes("chrome-extension://")) { extId = t.url.split("/")[2]; break; }
}
if (!extId) {
  // fallback: read the extension id from the load — use the known id from prior run
  extId = "bnglkgljoaoggjnghjlohjlhfcgpokgf";
}
console.log("extId:", extId);
const page = await cdp.send("Target.createTarget", { url: `chrome-extension://${extId}/ntp/ntp.html` });
const { sessionId } = await cdp.send("Target.attachToTarget", { targetId: page.targetId, flatten: true });
const sess = (m, p = {}, t = 60000) => cdp.send(m, p, sessionId, t);
await sess("Page.enable"); await sess("Runtime.enable");
await sleep(2500);
const st = await sess("Runtime.evaluate", { expression: `({ title: document.title, status: document.querySelector('#status')?.textContent, runBtn: !!document.querySelector('#run-task') })`, returnByValue: true });
console.log("hub:", JSON.stringify(st.result?.value));
// click run with a task
await sess("Runtime.evaluate", { expression: `(async () => {
  const inp = document.querySelector('#task-input'); inp.value = "summarize what the Chrome agent platform is";
  document.querySelector('#run-task').click();
  return "clicked";
})()`, awaitPromise: true, returnByValue: true });
// poll the status
for (let i = 0; i < 30; i++) {
  await sleep(2000);
  const s = await sess("Runtime.evaluate", { expression: `document.querySelector('#status')?.textContent`, returnByValue: true });
  const txt = s.result?.value;
  if (txt && !txt.includes("running")) { console.log("final status:", JSON.stringify(txt)); break; }
  if (i === 29) console.log("still running after 60s (hang?)");
}
// screenshot
const shot = await sess("Page.captureScreenshot", { format: "png" });
const bin = new Uint8Array(atob(shot.data).split("").map((c) => c.charCodeAt(0)));
await Deno.writeFile("/tmp/cap-e2e5/hub.png", bin);
proc.kill();
Deno.exit(0);
EOF
